"""Build the roadmap's generated files from its JSON sources.

Sources (edit these):  ideas.json, premises.json, biology.json, sources.json, summary.json
Generated (do not edit): IDEAS.md, ideas.csv, designs/*.md, biology-map.md, sources.md, map/index.html

Run from the project root:  python3 roadmap/build.py
"""
import csv
import json
import re
from pathlib import Path

ROOT = Path(__file__).parent
load = lambda name: json.loads((ROOT / name).read_text(encoding="utf-8"))

STATE = {
    "held": "Run: held up", "mixed": "Run: mixed", "failed": "Run: did not hold",
    "planned": "Planned earlier, not run", "registered": "Design registered", "seed": "Idea only",
}
FIELDS = [
    ("question", "Question"), ("result", "Result so far"), ("hypothesis", "Prediction"),
    ("falsifier", "What would refute it"), ("data", "Data"), ("method", "Method"),
    ("rivals", "Cheap rival it must beat"), ("premise", "Premise it tests"), ("bio", "Biology analogue"),
    ("cost", "Cost"), ("payoff", "Payoff"), ("risk", "Main risk"), ("review", "Reviewer note"), ("ranking", "Cross-area ranking"), ("overlaps", "Overlaps with"), ("note", "Note"),
]


def state(i):
    return (i.get("verdict") or "mixed") if i["status"] == "done" else i["status"]


def slug(text):
    return re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-")[:60]


def cell(text):
    return str(text or "").replace("|", "/").replace("\n", " ")


def main():
    db, prem, bio, src, summ = (load(n) for n in ("ideas.json", "premises.json", "biology.json", "sources.json", "summary.json"))
    regions = {r["id"]: r for r in db["regions"]}
    ideas = db["ideas"]
    ids = [i["id"] for i in ideas]
    assert len(ids) == len(set(ids)), "duplicate idea ids"
    for i in ideas:
        assert i["region"] in regions, f"{i['id']}: unknown region {i['region']}"
        assert i["status"] in ("done", "planned", "registered", "seed"), f"{i['id']}: bad status"

    # designs/*.md, one per registered design
    ddir = ROOT / "designs"
    ddir.mkdir(exist_ok=True)
    for old in ddir.glob("*.md"):
        if old.name != "README.md":
            old.unlink()
    for i in ideas:
        if i["status"] != "registered":
            continue
        out = [f"# {i['id']}: {i['title']}", "",
               f"**Area:** {regions[i['region']]['name']} · **Status:** design registered {db['registered']}, not run"
               + (f" · **Priority:** {i['priority']:.1f} of 5" if i.get("priority") else ""), ""]
        for key, label in FIELDS:
            if i.get(key):
                out += [f"## {label}", "", str(i[key]), ""]
        if i.get("sources"):
            out += ["## Sources", ""] + [f"- {s}" for s in i["sources"]] + [""]
        (ddir / f"{i['id']}-{slug(i['title'])}.md").write_text("\n".join(out), encoding="utf-8")

    # IDEAS.md and ideas.csv
    out = ["# Every idea, by area", "", "Generated by `build.py` from `ideas.json`. Do not edit by hand.", ""]
    for r in db["regions"]:
        rows = sorted((i for i in ideas if i["region"] == r["id"]), key=lambda i: -(i.get("priority") or 0))
        out += [f"## {r['name']}", "", r.get("blurb", ""), "", "| ID | Idea | Status | Priority | Cost |", "| --- | --- | --- | --- | --- |"]
        for i in rows:
            link = f"[{i['id']}](designs/{i['id']}-{slug(i['title'])}.md)" if i["status"] == "registered" else i["id"]
            pr = f"{i['priority']:.1f}" if i.get("priority") else ""
            out.append(f"| {link} | **{cell(i['title'])}**: {cell(i.get('question'))} | {STATE[state(i)]} | {pr} | {cell(i.get('cost'))} |")
        out.append("")
    (ROOT / "IDEAS.md").write_text("\n".join(out), encoding="utf-8")
    cols = ["id", "title", "region", "status", "verdict", "priority"] + [k for k, _ in FIELDS]
    with open(ROOT / "ideas.csv", "w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=cols + ["sources"], extrasaction="ignore")
        w.writeheader()
        for i in ideas:
            w.writerow({**i, "region": regions[i["region"]]["name"], "sources": "; ".join(i.get("sources", []))})

    # biology-map.md
    out = ["# The biology overlay", "", "Generated by `build.py` from `biology.json`. Do not edit by hand.", "",
           "## Tools", "", "| Biology tool | What it does | Memetic version | Ready now? | One experiment, and the rival to beat | Design |", "| --- | --- | --- | --- | --- | --- |"]
    out += [f"| {cell(b['tool'])} | {cell(b.get('does'))} | {cell(b['analogue'])} | {cell(b.get('feasibility'))} | {cell(b.get('experiment'))} | {cell(b.get('idea'))} |" for b in bio["tools"]]
    out += ["", "## Landmarks", "", "| Landmark | When | What it gave biology | The memetic version | Where memetics stands | Design |", "| --- | --- | --- | --- | --- | --- |"]
    out += [f"| {cell(l['who'])} | {cell(l['when'])} | {cell(l['gave'])} | {cell(l['memetic'])} | {cell(l.get('statusText'))} | {cell(l.get('idea'))} |" for l in bio["landmarks"]]
    (ROOT / "biology-map.md").write_text("\n".join(out) + "\n", encoding="utf-8")

    # sources.md
    out = ["# Reading list", "", "Generated by `build.py` from `sources.json`. Do not edit by hand.", "",
           "Rank A: read first. B: read when working in that area. C: background.", ""]
    for topic in dict.fromkeys(s.get("topic", "Other") for s in src):
        out += [f"## {topic}", ""]
        for s in sorted((s for s in src if s.get("topic", "Other") == topic), key=lambda s: s.get("priority", "C")):
            cite = f"[{s['cite']}]({s['url']})" if s.get("url") else s["cite"]
            out.append(f"- **{s.get('priority', 'C')}** {cite}. {s.get('why', '')}")
        out.append("")
    (ROOT / "sources.md").write_text("\n".join(out), encoding="utf-8")

    # map/index.html
    data = {"regions": db["regions"], "links": db.get("links", []), "ideas": ideas, "premises": prem, "biology": bio["tools"],
            "landmarks": bio["landmarks"], "sources": [s for s in src if s.get("priority") in ("A", "B")], "summary": summ}
    blob = json.dumps(data, ensure_ascii=False).replace("</", "<\\/")
    page = (ROOT / "map/template.html").read_text(encoding="utf-8")
    page = page.replace("/*STYLE*/", (ROOT / "map/style.css").read_text(encoding="utf-8"))
    page = page.replace("/*DATA*/", blob).replace("/*APP*/", (ROOT / "map/app.js").read_text(encoding="utf-8"))
    (ROOT / "map/index.html").write_text(page, encoding="utf-8")
    n = lambda k: sum(1 for i in ideas if state(i) == k)
    print(f"{len(ideas)} ideas: {sum(1 for i in ideas if i['status'] == 'done')} run, {n('planned')} planned earlier, "
          f"{n('registered')} registered, {n('seed')} seeds; {len(bio['tools'])} biology tools; {len(src)} sources")


if __name__ == "__main__":
    main()
